16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	import org.springframework.samples.petclinic.util.RegistrationDatePolicy;
20	
21	import jakarta.persistence.*;
22	import jakarta.validation.constraints.NotEmpty;
23	import jakarta.validation.constraints.Pattern;
24	
25	import java.time.LocalDate;
26	import java.util.*;
27	
28	/**
29	 * Simple JavaBean domain object representing an owner.
30	 *
31	 * @author Ken Krebs
32	 * @author Juergen Hoeller
33	 * @author Sam Brannen
34	 * @author Michael Isvy
35	 */
36	@Entity
37	@Table(name = "owners")
38	public class Owner extends Person {
39	    @Column(name = "address")
40	    @NotEmpty
41	    private String address;
42	
43	    @Column(name = "city")
44	    @NotEmpty
45	    private String city;
46	
47	    @Column(name = "telephone")
48	    @NotEmpty
49	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form")
50	    private String telephone;
51	
52	    @Column(name = "email")
53	    private String email;
54	
55	    @Column(name = "registration_date")
56	    private LocalDate registrationDate;
57	
58	    @Column(name = "customer_code")
59	    private String customerCode;
60	
61	    @Column(name = "household_id")
62	    private String householdId;
63	
64	    @Column(name = "namesake_count")
65	    private Integer namesakeCount;
66	
67	    @Column(name = "household_size")
68	    private Integer householdSize;
69	
70	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
71	    private Set<Pet> pets;
72	
73	    /**
74	     * Resolve the registration date at creation time: default it to the server's
75	     * current date when none was supplied, and roll a weekend date forward to the
76	     * next business day so every value derived from it (such as the membership
77	     * number's year segment) uses the adjusted date.
78	     */
79	    @PrePersist
80	    private void resolveRegistrationDate() {
81	        this.registrationDate = RegistrationDatePolicy.effectiveDate(this.registrationDate);
82	    }
83	
84	    public String getAddress() {
85	        return this.address;
86	    }
87	
88	    public void setAddress(String address) {
89	        this.address = address;
90	    }
91	
92	    public String getCity() {
93	        return this.city;
94	    }
95	
96	    public void setCity(String city) {
97	        this.city = city;
98	    }
99	
100	    /**
101	     * The owner's locality: the canonical region derived from its {@link #city}
102	     * via the fixed {@link CityRegion} table, or {@code "UNKNOWN"} when the city
103	     * is not in the table.
104	     */
105	    public String getLocality() {
106	        return CityRegion.regionFor(this.city);
107	    }
108	
109	    public String getTelephone() {
110	        return this.telephone;
111	    }
112	
113	    public void setTelephone(String telephone) {
114	        this.telephone = telephone;
115	    }
116	
117	    public String getEmail() {
118	        return this.email;
119	    }
120	
121	    public void setEmail(String email) {
122	        this.email = email;
123	    }
124	
125	    public LocalDate getRegistrationDate() {
126	        return this.registrationDate;
127	    }
128	
129	    public void setRegistrationDate(LocalDate registrationDate) {
130	        this.registrationDate = registrationDate;
131	    }
132	
133	    public String getCustomerCode() {
134	        return this.customerCode;
135	    }
136	
137	    public void setCustomerCode(String customerCode) {
138	        this.customerCode = customerCode;
139	    }
140	
141	    /**
142	     * The owner's membership number, formatted {@code '<customerCode>-M<YY>'}
143	     * where {@code YY} is the last two digits of the {@link #registrationDate}
144	     * year (e.g. {@code "LON-SMI-0007-M26"}). Derived from the owner's own fields.
145	     */
146	    public String getMembershipNumber() {
147	        if (this.customerCode == null || this.registrationDate == null) {
148	            return null;
149	        }
150	        return String.format("%s-M%02d", this.customerCode, this.registrationDate.getYear() % 100);
151	    }
152	
153	    public String getHouseholdId() {
154	        return this.householdId;
155	    }
156	
157	    public void setHouseholdId(String householdId) {
158	        this.householdId = householdId;
159	    }
160	
161	    /**
162	     * The owner's membership level, a number from 1 to 3 derived from the
163	     * owner's own fields. Starts at {@code 1}, gains {@code 1} when a contact
164	     * email is on file, gains {@code 1} when the owner has no namesakes, and is
165	     * capped at {@code 3}. (Level {@code 4} is reserved for tenure.)
166	     */
167	    public Integer getMembershipLevel() {
168	        int level = 1;
169	        boolean hasEmail = this.email != null && !this.email.isEmpty();
170	        if (hasEmail) {
171	            level += 1;
172	        }
173	        boolean noNamesakes = this.namesakeCount != null && this.namesakeCount == 0;
174	        if (noNamesakes) {
175	            level += 1;
176	        }
177	        return Math.min(level, 3);
178	    }
179	
180	    /**
181	     * The owner's preferred contact channel, derived from the fields on file:
182	     * {@code "EMAIL"} when a contact email is present, otherwise {@code "PHONE"}.
183	     */
184	    public String getContactPreference() {
185	        boolean hasEmail = this.email != null && !this.email.isEmpty();
186	        return hasEmail ? "EMAIL" : "PHONE";
187	    }
188	
189	    public Integer getNamesakeCount() {
190	        return this.namesakeCount;
191	    }
192	
193	    public void setNamesakeCount(Integer namesakeCount) {
194	        this.namesakeCount = namesakeCount;
195	    }
196	
197	    public Integer getHouseholdSize() {
198	        return this.householdSize;
199	    }
200	
201	    public void setHouseholdSize(Integer householdSize) {
202	        this.householdSize = householdSize;
203	    }
204	
205	    protected Set<Pet> getPetsInternal() {
206	        if (this.pets == null) {
207	            this.pets = new HashSet<>();
208	        }
209	        return this.pets;
210	    }
211	
212	    protected void setPetsInternal(Set<Pet> pets) {
213	        this.pets = pets;
214	    }
215	
216	    public List<Pet> getPets() {
217	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
218	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
219	        return Collections.unmodifiableList(sortedPets);
220	    }
221	
222	    public void setPets(List<Pet> pets) {
223	        this.pets = new HashSet<>(pets);
224	    }
225	
226	    public void addPet(Pet pet) {
227	        getPetsInternal().add(pet);
228	        pet.setOwner(this);
229	    }
230	
231	    /**
232	     * Return the Pet with the given name, or null if none found for this Owner.
233	     *
234	     * @param name to test
235	     * @return true if pet name is already in use
236	     */
237	    public Pet getPet(String name) {
238	        return getPet(name, false);
239	    }
240	
241	    /**
242	     * Return the Pet with the given name, or null if none found for this Owner.
243	     *
244	     * @param name to test
245	     * @return true if pet name is already in use
246	     */
247	    public Pet getPet(String name, boolean ignoreNew) {
248	        name = name.toLowerCase();
249	        for (Pet pet : getPetsInternal()) {
250	            if (!ignoreNew || !pet.isNew()) {
251	                String compName = pet.getName();
252	                compName = compName.toLowerCase();
253	                if (compName.equals(name)) {
254	                    return pet;
255	                }
256	            }
257	        }
258	        return null;
259	    }
260	
261	    public Pet getPet(Integer petId) {
262	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
263	    }
264	
265	    @Override
266	    public String toString() {
267	        return new ToStringCreator(this)
268	
269	            .append("id", this.getId())
270	            .append("new", this.isNew())
271	            .append("lastName", this.getLastName())
272	            .append("firstName", this.getFirstName())
273	            .append("address", this.address)
274	            .append("city", this.city)
275	            .append("telephone", this.telephone)
276	            .append("email", this.email)
277	            .toString();
278	    }
279	}
