135	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
136	    @Override
137	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
138	        ownerFieldsDto.setAddress(AddressNormalizer.normalize(ownerFieldsDto.getAddress()));
139	        List<String> missingFields = OwnerFieldsValidator.findMissingFields(ownerFieldsDto);
140	        if (!missingFields.isEmpty()) {
141	            throw new MissingOwnerFieldsException(missingFields);
142	        }
143	        HttpHeaders headers = new HttpHeaders();
144	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
145	        if (this.clinicService.countOwnersByCity(owner.getCity()) >= MAX_OWNERS_PER_CITY) {
146	            throw new CityCapacityExceededException(owner.getCity());
147	        }
148	        LocalDate registrationDate = RegistrationDatePolicy.effectiveDate(owner.getRegistrationDate());
149	        if (this.clinicService.countOwnersRegisteredOn(registrationDate) >= MAX_OWNERS_PER_DAY) {
150	            throw new DailyOwnerLimitExceededException(registrationDate);
151	        }
152	        String telephone = TelephoneNormalizer.normalize(owner.getTelephone());
153	        if (!this.clinicService.findOwnerByTelephone(telephone).isEmpty()) {
154	            throw new DuplicateTelephoneException(telephone);
155	        }
156	        String email = EmailNormalizer.normalize(owner.getEmail());
157	        if (email != null && !this.clinicService.findOwnerByEmail(email).isEmpty()) {
158	            throw new DuplicateEmailException(email);
159	        }
160	        Collection<Owner> household =
161	            this.clinicService.findOwnersInHousehold(owner.getLastName(), owner.getAddress());
162	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
163	        if (!household.isEmpty() && !sharesHousehold) {
164	            throw new DuplicateHouseholdException(owner.getLastName(), owner.getAddress());
165	        }
166	        owner.setTelephone(telephone);
167	        owner.setEmail(email);
168	        if (sharesHousehold) {
169	            this.clinicService.joinHousehold(owner, household);
170	        }
171	        this.clinicService.saveOwner(owner);
172	        this.ownerAuditor.ownerCreated(owner);
173	        OwnerDto ownerDto = toOwnerDtoWithBulkSignupWarning(owner);
174	        headers.setLocation(UriComponentsBuilder.newInstance()
175	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
176	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
177	    }
178	
179	    /**
180	     * Map an owner to its DTO and stamp {@code bulkSignupWarning}, which reflects whether more than
181	     * {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been registered on the current
182	     * business day.
183	     */
184	    private OwnerDto toOwnerDtoWithBulkSignupWarning(Owner owner) {
185	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
186	        LocalDate today = RegistrationDatePolicy.effectiveDate(null);
187	        ownerDto.setBulkSignupWarning(
188	            this.clinicService.countOwnersRegisteredOn(today) > BULK_SIGNUP_WARNING_THRESHOLD);
189	        return ownerDto;
190	    }
