48	/**
49	 * Global Exception handler for REST controllers.
50	 * <p>
51	 * This class handles exceptions thrown by REST controllers and returns appropriate HTTP responses to the client.
52	 *
53	 * @author Vitaliy Fedoriv
54	 * @author Alexander Dudkin
55	 */
56	@ControllerAdvice
57	public class ExceptionControllerAdvice {
58	
59	    private static final Logger logger = LoggerFactory.getLogger(ExceptionControllerAdvice.class);
60	    private static final String ERROR_UNEXPECTED = "An unexpected error occurred while processing your request";
61	    private static final String ERROR_DATA_INTEGRITY = "The requested resource could not be processed due to a data constraint violation";
62	    private static final String ERROR_INVALID_REQUEST = "The request contains invalid or missing parameters";
63	    private static final String ERROR_DUPLICATE_TELEPHONE = "An owner with the given telephone number already exists";
64	    private static final String ERROR_DUPLICATE_EMAIL = "An owner with the given email already exists";
65	    private static final String ERROR_DUPLICATE_HOUSEHOLD = "An owner with the same last name and address already exists";
66	    private static final String ERROR_CITY_AT_CAPACITY = "The owner's city has already reached its maximum number of owners";
67	    private static final String ERROR_DAILY_LIMIT_REACHED = "The maximum number of owners that may be registered today has already been reached";
68	
69	    /**
70	     * Private method for constructing the {@link ProblemDetail} object passing the name and details of the exception
71	     * class.
72	     *
73	     * @param e     Object referring to the thrown exception.
74	     * @param status HTTP response status.
75	     * @param url URL request.
76	     */
77	    private ProblemDetail detailBuild(Exception e, HttpStatus status, StringBuffer url, String detail) {
78	        ProblemDetail problemDetail = ProblemDetail.forStatus(status);
79	        problemDetail.setType(URI.create(url.toString()));
80	        problemDetail.setTitle(e.getClass().getSimpleName());
81	        problemDetail.setDetail(detail);
82	        problemDetail.setProperty("timestamp", Instant.now());
83	        problemDetail.setProperty("schemaValidationErrors", List.<ValidationMessageDto>of());
84	        return problemDetail;
85	    }
86	
87	    /**
88	     * Re-throws {@link AccessDeniedException} so Spring Security's {@code ExceptionTranslationFilter}
89	     * translates it as it normally would - 403 for an authenticated user lacking the required role,
90	     * or the configured entry point for an anonymous one. Without this, {@link #handleGeneralException}
91	     * would catch it and report an authorization failure as a 500.
92	     *
93	     * @param e The {@link AccessDeniedException} to propagate
94	     * @throws AccessDeniedException always
95	     */
96	    @ExceptionHandler(AccessDeniedException.class)
97	    public void handleAccessDeniedException(AccessDeniedException e) throws AccessDeniedException {
98	        throw e;
99	    }
100	
101	    /**
102	     * Handles all general exceptions by returning a 500 Internal Server Error status with error details.
103	     *
104	     * @param e The {@link Exception} to be handled
105	     * @param request {@link HttpServletRequest} object referring to the current request.
106	     * @return A {@link ResponseEntity} containing the error information and a 500 Internal Server Error status
107	     */
108	    @ExceptionHandler(Exception.class)
109	    @ResponseBody
110	    public ResponseEntity<ProblemDetail> handleGeneralException(Exception e, HttpServletRequest request) {
111	        logger.error("Unexpected error at {} {}", request.getMethod(), request.getRequestURI(), e);
112	        HttpStatus status = HttpStatus.INTERNAL_SERVER_ERROR;
113	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_UNEXPECTED);
114	        return ResponseEntity.status(status).body(detail);
115	    }
116	
117	    /**
118	     * Handles {@link DataIntegrityViolationException} which typically indicates database constraint violations. This
119	     * method returns a 404 Not Found status if an entity does not exist.
120	     *
121	     * @param e The {@link DataIntegrityViolationException} to be handled
122	     * @param request {@link HttpServletRequest} object referring to the current request.
123	     * @return A {@link ResponseEntity} containing the error information and a 404 Not Found status
124	     */
125	    @ExceptionHandler(DataIntegrityViolationException.class)
126	    @ResponseBody
127	    public ResponseEntity<ProblemDetail> handleDataIntegrityViolationException(DataIntegrityViolationException e, HttpServletRequest request) {
128	        logger.warn("Data integrity violation at {} {}: {}",
129	            request.getMethod(),
130	            request.getRequestURI(),
131	            e.getMessage());
132	        logger.debug("Data integrity violation stacktrace", e);
133	        HttpStatus status = HttpStatus.NOT_FOUND;
134	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
135	        return ResponseEntity.status(status).body(detail);
136	    }
137	
138	    /**
139	     * Handles exception thrown by Bean Validation on controller methods parameters
140	     *
141	     * @param e The {@link MethodArgumentNotValidException} to be handled
142	     * @param request {@link HttpServletRequest} object referring to the current request.
143	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
144	     */
145	    @ExceptionHandler(MethodArgumentNotValidException.class)
146	    @ResponseBody
147	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
148	        HttpStatus status = HttpStatus.BAD_REQUEST;
149	        BindingErrorsResponse errors = new BindingErrorsResponse();
150	        BindingResult bindingResult = e.getBindingResult();
151	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
152	        if (bindingResult.hasErrors()) {
153	            errors.addAllErrors(bindingResult);
154	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
155	                .map(fieldError -> {
156	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
157	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
158	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
159	                        fieldError.getField(),
160	                        defaultMessage,
161	                        rejectedValue);
162	                    return new ValidationMessageDto(message)
163	                        .putAdditionalProperty("field", fieldError.getField())
164	                        .putAdditionalProperty("rejectedValue", rejectedValue)
165	                        .putAdditionalProperty("defaultMessage", defaultMessage);
166	                })
167	                .toList();
168	            logger.debug("Validation error at {} {}: {}",
169	                request.getMethod(),
170	                request.getRequestURI(),
171	                bindingResult.getFieldErrors());
172	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
173	            List<String> invalidFields = bindingResult.getFieldErrors().stream()
174	                .map(FieldError::getField)
175	                .distinct()
176	                .toList();
177	            detail.setProperty("errors", invalidFields);
178	            return ResponseEntity.status(status).body(detail);
179	        }
180	        return ResponseEntity.status(status).body(detail);
181	    }
182	
183	    /**
184	     * Handles {@link MissingOwnerFieldsException} raised when a request to create or update an owner
185	     * omits one or more mandatory fields, returning a 400 Bad Request whose {@code errors} array lists
186	     * the name of each missing field.
187	     *
188	     * @param e The {@link MissingOwnerFieldsException} to be handled
189	     * @param request {@link HttpServletRequest} object referring to the current request.
190	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
191	     */
192	    @ExceptionHandler(MissingOwnerFieldsException.class)
193	    @ResponseBody
194	    public ResponseEntity<ProblemDetail> handleMissingOwnerFieldsException(MissingOwnerFieldsException e, HttpServletRequest request) {
195	        HttpStatus status = HttpStatus.BAD_REQUEST;
196	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
197	        detail.setProperty("errors", e.getFields());
198	        return ResponseEntity.status(status).body(detail);
199	    }
200	
201	    /**
202	     * Handles {@link InvalidTelephoneException} raised when a submitted telephone number cannot be
203	     * converted to a valid E.164 value, returning a 400 Bad Request.
204	     *
205	     * @param e The {@link InvalidTelephoneException} to be handled
206	     * @param request {@link HttpServletRequest} object referring to the current request.
207	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
208	     */
209	    @ExceptionHandler(InvalidTelephoneException.class)
210	    @ResponseBody
211	    public ResponseEntity<ProblemDetail> handleInvalidTelephoneException(InvalidTelephoneException e, HttpServletRequest request) {
212	        HttpStatus status = HttpStatus.BAD_REQUEST;
213	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
214	        detail.setProperty("errors", List.of("telephone"));
215	        return ResponseEntity.status(status).body(detail);
216	    }
217	
218	    /**
219	     * Handles {@link DuplicateTelephoneException} raised when a new owner is submitted with a normalized
220	     * telephone number that is already used by an existing owner, returning a 409 Conflict.
221	     *
222	     * @param e The {@link DuplicateTelephoneException} to be handled
223	     * @param request {@link HttpServletRequest} object referring to the current request.
224	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
225	     */
226	    @ExceptionHandler(DuplicateTelephoneException.class)
227	    @ResponseBody
228	    public ResponseEntity<ProblemDetail> handleDuplicateTelephoneException(DuplicateTelephoneException e, HttpServletRequest request) {
